  if (typeof header !== 'string' || Buffer.byteLength(header) > 4096) return [];
  return header.split(';').map((part) => part.trim()).filter((part) => part.startsWith(`${COOKIE_NAME}=`)).map((part) => part.slice(COOKIE_NAME.length + 1));
