    this._append('session.issued', auth.actor, payload);
    const maxAge = Math.floor(fields.ttlMs / 1000);
    return freeze({
      sessionId, credentialId, token: rawToken, ...(rawCsrf ? { csrfToken: rawCsrf } : {}),
      expiresAt: payload.expiresAt,
      ...(fields.authMethod === 'cookie' ? { setCookie: `${COOKIE_NAME}=${rawToken}; Max-Age=${maxAge}; Secure; HttpOnly; SameSite=Strict; Path=/` } : {}),
    });
  }

  revoke(sessionId, auth = {}) {
    const session = this._sessions.get(sessionId);
    if (!session || session.revoked) return freeze({ ok: true, result: 'not_active' });
    const event = this._append('session.revoked', auth.actor, { sessionId, reason: auth.reason ?? null });
    return freeze({ ok: true, result: 'revoked', event: clone(event), clearCookie: `${COOKIE_NAME}=; Max-Age=0; Secure; HttpOnly; SameSite=Strict; Path=/` });
  }

  rotate(sessionId, auth = {}) {
    const old = this._sessions.get(sessionId);
    if (!old || old.revoked || Date.parse(old.expiresAt) <= this.now()) return null;
    const rawToken = token();
    const rawCsrf = old.authMethod === 'cookie' ? token() : null;
    const issuedAtMs = this.now();
    const originalTtl = Date.parse(old.expiresAt) - Date.parse(old.issuedAt);
    const ttlMs = Math.min(this.maxTtlMs, Math.max(1, old.ttlMs ?? originalTtl));
    const successor = {
      sessionId: randomUUID(), credentialId: randomUUID(), userId: old.userId, authMethod: old.authMethod,
      capabilities: [...old.capabilities], repoIds: [...old.repoIds], tokenDigest: digest(rawToken),
      ...(rawCsrf ? { csrfTokenDigest: digest(rawCsrf) } : {}), ttlMs,
      issuedAt: new Date(issuedAtMs).toISOString(), expiresAt: new Date(issuedAtMs + ttlMs).toISOString(),
    };
    this._append('session.rotated', auth.actor, { predecessorSessionId: old.sessionId, successor });
    return freeze({
      sessionId: successor.sessionId, credentialId: successor.credentialId, token: rawToken,
      ...(rawCsrf ? { csrfToken: rawCsrf } : {}), expiresAt: successor.expiresAt,
      ...(old.authMethod === 'cookie' ? { setCookie: `${COOKIE_NAME}=${rawToken}; Max-Age=${Math.floor(ttlMs / 1000)}; Secure; HttpOnly; SameSite=Strict; Path=/` } : {}),
    });
  }

  authenticate(req) {
    const authorization = req?.headers?.authorization;
    const cookies = cookieTokens(req?.headers?.cookie);
    if (authorization !== undefined && cookies.length > 0) return null;
    let rawToken; let authMethod;
    if (authorization !== undefined) {
      if (typeof authorization !== 'string' || Buffer.byteLength(authorization) > this.maxCredentialBytes) return null;
      const match = /^Bearer ([A-Za-z0-9_-]{40,128})$/.exec(authorization);
      if (!match) return null;
      rawToken = match[1]; authMethod = 'bearer';
    } else if (cookies.length === 1) {
      if (Buffer.byteLength(cookies[0]) > this.maxCredentialBytes || !/^[A-Za-z0-9_-]{40,128}$/.test(cookies[0])) return null;
      rawToken = cookies[0]; authMethod = 'cookie';
    } else return null;
    const sessionId = this._byDigest.get(digest(rawToken));
    const session = this._sessions.get(sessionId);
    if (!session || session.revoked || session.authMethod !== authMethod || Date.parse(session.expiresAt) <= this.now()) return null;
    return freeze({
      userId: session.userId, sessionId: session.sessionId, credentialId: session.credentialId,
      authMethod: session.authMethod, issuedAt: session.issuedAt, expiresAt: session.expiresAt,
      capabilities: [...session.capabilities], repoIds: [...session.repoIds], revoked: false,
      ...(session.csrfTokenDigest ? { csrfTokenDigest: session.csrfTokenDigest } : {}),
    });
  }

  isPrincipalActive(principal, context = {}) {
    const session = this._sessions.get(principal?.sessionId);
    if (!session || session.revoked || Date.parse(session.expiresAt) <= this.now()) return false;
    if (session.userId !== principal.userId || session.credentialId !== principal.credentialId
      || session.authMethod !== principal.authMethod || session.expiresAt !== principal.expiresAt) return false;
    if (context.repoId && !session.repoIds.includes(context.repoId)) return false;
    if (!Array.isArray(principal.capabilities)
      || principal.capabilities.some((capability) => !session.capabilities.includes(capability))) return false;
    if (!Array.isArray(principal.repoIds)
      || principal.repoIds.some((repoId) => !session.repoIds.includes(repoId))) return false;
    return true;
  }

  authenticator() {
    const authenticate = (req) => this.authenticate(req);
    authenticate.isPrincipalActive = (principal, context) => this.isPrincipalActive(principal, context);
    return authenticate;
  }
}

