 45	  assert.equal(sessions.events().at(-1).kind, 'session.rotated');
 46	  assert.equal(sessions.authenticate(bearer(first.token)), null);
 47	  assert.deepEqual(sessions.authenticate(bearer(next.token)).capabilities, ['observe']);
 48	  const durable = readFileSync(join(directory, 'sessions.jsonl'), 'utf8');
 49	  assert.equal(durable.includes(first.token), false);
